package transport

import (
    "encoding/json"
    "fmt"
    "io"
    "strings"
)

type CreateOrder struct {
    ProductID string `json:"product_id"`
    Quantity int `json:"quantity"`
}

func DecodeCreateOrder(r io.Reader) (CreateOrder, error) {
    dec := json.NewDecoder(io.LimitReader(r, 1<<20))
    dec.DisallowUnknownFields()
    var req CreateOrder
    if err := dec.Decode(&req); err != nil {
        return CreateOrder{}, fmt.Errorf("decode create order: %w", err)
    }
    var extra any
    if err := dec.Decode(&extra); err != io.EOF {
        return CreateOrder{}, fmt.Errorf("request must contain one JSON value")
    }
    if strings.TrimSpace(req.ProductID) == "" || req.Quantity <= 0 {
        return CreateOrder{}, fmt.Errorf("invalid product_id or quantity")
    }
    return req, nil
}

