package config

import (
    "fmt"
    "time"
)

func ParseTimeout(raw string) (time.Duration, error) {
    d, err := time.ParseDuration(raw)
    if err != nil {
        return 0, fmt.Errorf("parse timeout %q: %w", raw, err)
    }
    if d < 100*time.Millisecond || d > 30*time.Second {
        return 0, fmt.Errorf("timeout must be between 100ms and 30s")
    }
    return d, nil
}
